    ("    private static void testChipVisualSettingsBounds() {", "    private static void testWireJunctionFanout() {\n        CircuitDocument document = new CircuitDocument();\n        EditorNode input = document.addNode(NodeKind.INPUT, 0, 0);\n        input.width = 8;\n        EditorNode junction = document.addNode(NodeKind.JUNCTION, 80, 0);\n        junction.width = 8;\n        EditorNode outA = document.addNode(NodeKind.OUTPUT, 160, -30);\n        outA.width = 8;\n        EditorNode outB = document.addNode(NodeKind.OUTPUT, 160, 30);\n        outB.width = 8;\n        document.connect(input.id, 0, junction.id, 0);\n        document.connect(junction.id, 0, outA.id, 0);\n        document.connect(junction.id, 0, outB.id, 0);\n        CompiledCircuit compiled = CircuitCompiler.compile(document, name -> null);\n        compiled.driveInputUnsigned(input.id, 0xA5L);\n        check(compiled.inputUnsigned(outA.id, 0) == 0xA5L, \"junction fanout A carries shared value\");\n        check(compiled.inputUnsigned(outB.id, 0) == 0xA5L, \"junction fanout B carries shared value\");\n        compiled.driveInputUnsigned(input.id, 0x3CL);\n        check(compiled.inputUnsigned(outA.id, 0) == 0x3CL && compiled.inputUnsigned(outB.id, 0) == 0x3CL, \"junction branches update together\");\n    }\n\n    private static void testChipVisualSettingsBounds() {"),
